/**
  * @brief  Probe the ST1633I TS driver.
  * @param  Instance TS Instance.
  * @retval BSP status.
  */
static int32_t ST1633I_Probe(uint32_t Instance)
{
  int32_t ret               = BSP_ERROR_NONE;
  ST1633I_IO_t              IOCtx;
  static ST1633I_Object_t   ST1633IObj;

  /* Configure the TS driver */
  IOCtx.Address     = TS_I2C_ADDRESS;
  IOCtx.Init        = BSP_I2C1_Init;
  IOCtx.DeInit      = BSP_I2C1_DeInit;
  IOCtx.ReadReg     = BSP_I2C1_ReadReg;
  IOCtx.WriteReg    = BSP_I2C1_WriteReg;
  IOCtx.GetTick     = BSP_GetTick;

  if (ST1633I_RegisterBusIO(&ST1633IObj, &IOCtx) != ST1633I_OK)
  {
    ret = BSP_ERROR_BUS_FAILURE;
  }
  else
  {
    Ts_CompObj[Instance] = &ST1633IObj;
    Ts_Drv = (TS_Drv_t *) &ST1633I_TS_Driver;
    if (Ts_Drv->Init(Ts_CompObj[Instance]) < 0)
    {
      ret = BSP_ERROR_COMPONENT_FAILURE;
    }
  }

  return ret;
}

